// TH14 synthetic training aliases used by this card (see transcribe/th14/touhou-bullets.ecl).
// Native 0..23 -> modern same number; native 24..42 -> modern +1. Base radii already checked.
const TH14_BALL: int = 416;   // native type 4 (etSprite(1,4,8)), radius 4, colors 0..15

// TH14 v1.00b st04.ecl.txt::MainSub04 / MainSub04b / ECir01 / ECir01_at (source lines 1141-1173, 158-274).
// Source t0 = card frame 120 (opening buffer). Source has no time limit; 2800 is the
// schedule/exit/tail estimate, so TIME_LIMIT = 120 + 2800 + 4 startup margin.
const TIME_LIMIT: int = 2924;
const OPENING_BUFFER: int = 120;

// Src 0158-0191 ECir01. Created by enmCreateMF/F("ECir01",0,32,150,1000,1) -> final (0,32), HP150.
// side is source %A taken from the child mirror: enmCreateMF sets mirror=1 -> A=-1, enmCreateF -> A=+1.
async sub ecir01(side: int) {
    set_invuln(65535);
    // 0167-0168 setHurtbox(24,24)/setHitbox(16,16), common circle branch -> radius 12 / 8.
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // 0178 movePosRel(-192*A,0) writes the REL layer; the creation position stays as ABS.
    // Anm select/sprite/scale/alpha/color and drop*/flag 15 belong to the spawn fade (omitted).
    move_to(0, (-192*side) as fx, 32fx, EASE_LINEAR);
    // 0179 moveBezierRel(120, 256A,-30, 160A,128, 0,0): Hermite on REL, endpoint absolute in REL.
    hermite_start(0, (-192*side) as fx, (160*side) as fx, (256*side) as fx, 0fx, 120);
    hermite_start(1, 0fx, 128fx, -30fx, 0fx, 120);
    for m in 0..120 {
        wait(1);
        move_to(0, hermite_value(0), 32fx + hermite_value(1), EASE_LINEAR);
    }
    // 0180-0184 wait(120) done, spawn state cleared, @ECir01_at async: same next-frame start.
    spawn ecir01_at();
    // 0183 moveBezierRel(120, 0,0, -220A,192, -200A,-228), runs while the attacker fires.
    hermite_start(2, (160*side) as fx, (-220*side) as fx, 0fx, (-200*side) as fx, 120);
    hermite_start(3, 128fx, 192fx, 0fx, -228fx, 120);
    for q in 0..120 {
        wait(1);
        move_to(0, hermite_value(2), 32fx + hermite_value(3), EASE_LINEAR);
    }
    // 0186-0190 source loops wait(1000) forever; the enemy leaves the field at x = -220*A.
    loop { wait(1); }
}

// Src 0193-0274 ECir01_at. Every value below is the source !E/!N/!H/!LO column.
async sub ecir01_at() {
    var rank: int = global(GVAR_RANK);
    // 0196-0205 first wait: E10 N10 H0 L0.
    if rank <= RANK_NORMAL { wait(10); }
    // 0209-0226 etSpeed(0, 2.7, 4.0, 4.0, 5.0) twice; one layer uses the first value only.
    var lspd: fx = 2.7fx;
    if rank == RANK_NORMAL || rank == RANK_HARD { lspd = 4fx; }
    if rank == RANK_LUNATIC { lspd = 5fx; }
    // 0227-0236 laserNew(0, 0, L, 0, 14) target length L: E128 N160 H144 L160.
    var llen: fx = 128fx;
    if rank == RANK_NORMAL || rank == RANK_LUNATIC { llen = 160fx; }
    if rank == RANK_HARD { llen = 144fx; }
    // 0238 diffI($C,1,1,2,5) bursts; 0242 diffI($D,3,5,5,7) lasers per burst.
    var c: int = 1;
    if rank == RANK_HARD { c = 2; }
    if rank == RANK_LUNATIC { c = 5; }
    var d: int = 3;
    if rank == RANK_NORMAL || rank == RANK_HARD { d = 5; }
    if rank == RANK_LUNATIC { d = 7; }
    // 0247 diffF(%B, 30deg, 22.5deg, 22.5deg, 18deg) per-laser sweep step.
    var step: int = 5461;
    if rank == RANK_NORMAL || rank == RANK_HARD { step = 4096; }
    if rank == RANK_LUNATIC { step = 3277; }
    // 0261-0269 trailing wait: E60 N50 H20 L10.
    var gap: int = 60;
    if rank == RANK_NORMAL { gap = 50; }
    if rank == RANK_HARD { gap = 20; }
    if rank == RANK_LUNATIC { gap = 10; }
    for n in 0..c {
        // 0245 etAngle(0, ANGLE_PLAYER + %A, 0): one aim read per burst (all same frame).
        var aim: int = aim_player() as int;
        var a: int = 8192;                       // 0241 %A = 0.785398 (45deg)
        for k in 0..d {
            // 0700/0702 laserNew+laserOn at the current enemy position. Source w=14 (<32, Line):
            // native half height w/4 = 3.5 -> target full width 7; whole-beam judgment (laser_approx).
            var lz: int = laser(3, $self_x, $self_y, (aim+a) as angle, 0fx, 7fx, 0, 9999, 0);
            lz_speed(lz, lspd, llen);            // grows 0->L at the et speed, then travels outward
            a = a - step;                        // 0248 %A = %A - %B
        }
        // 0251-0259 unless DIFF>=1: etAim(1,8) (random angle and speed), etSprite(1,4,8),
        // etCount(1,8,1), etAngle(1, ANGLE_PLAYER-15deg, 30deg), etSpeed(1, 1.0, 2.0).
        if rank >= RANK_NORMAL {
            var alpha: int = aim - 2731;         // 0.2617994 rad = 15deg
            for j in 0..8 {
                var ra: int = rand(65536);
                var ua: fx = (ra-32768) as fx / 32768;
                var off: int = (5461fx*ua) as int;    // 30deg random amplitude
                var bang: angle = (alpha+off) as angle;
                var rv: int = rand(65536);
                var us: fx = (rv-32768) as fx / 65536 + 0.5fx;
                var bspd: fx = 1fx + 2fx*us;          // s0 1.0 + U*s1 2.0
                // 0258 etEx ANIM a=1: birth position -= 4*velocity (a/b/r/s unused here).
                _ = fire(TH14_BALL, 8,
                         $self_x - 4fx*bspd*cos(bang),
                         $self_y - 4fx*bspd*sin(bang),
                         bspd, bang, none, none);
            }
        }
        wait(gap);                               // 0270 wait, then 0272 if ($C--) repeat
    }
}

// 1144-1155 MainSub04: async MainSub04b, then 7 creations 180 frames apart at source t0..1080.
async sub path_a() {
    for k in 0..7 {
        _ = spawn_enemy(0fx, 32fx, 150, 0, 1000, 0, ecir01(-1));  // enmCreateMF: child mirror=1
        wait(180);
    }
}

// 1158-1171 MainSub04b: wait 90, then 7 creations 180 frames apart at source t90..1170.
async sub path_b() {
    wait(90);
    for k in 0..7 {
        _ = spawn_enemy(0fx, 32fx, 150, 0, 1000, 0, ecir01(1));   // enmCreateF: child mirror=0
        wait(180);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn path_a();
    spawn path_b();
    loop { wait(60); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
